import{_ as l,a0 as r,w as p,s as d,I as t,x as e,a1 as i,A as n,ao as o}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const S=JSON.parse('{"title":"在 Fedora 上為 SSH 設置雙因子驗證 | LCTT x X-CMD","titleTemplate":false,"description":"在 Fedora 上為 SSH 設置雙因子驗證 | LCTT (201903) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 Fedora 上為 SSH 設置雙因子驗證 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 Fedora 上為 SSH 設置雙因子驗證 | LCTT (201903) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201903/20190220 Set up two-factor authentication for SSH on Fedora","title":"在 Fedora 上為 SSH 設置雙因子驗證","tag":"201903","desc":""},"relativePath":"201903/20190220 Set up two-factor authentication for SSH on Fedora.md","filePath":"[post].md"}'),h={name:"201903/20190220 Set up two-factor authentication for SSH on Fedora.md"};function g(u,s,k,b,c,f){const a=r("Link");return p(),d("div",null,[s[28]||(s[28]=t("h1",{id:"在-fedora-上為-ssh-設置雙因子驗證",tabindex:"-1"},[e("在 Fedora 上為 SSH 設置雙因子驗證 "),t("a",{class:"header-anchor",href:"#在-fedora-上為-ssh-設置雙因子驗證","aria-label":"Permalink to “在 Fedora 上為 SSH 設置雙因子驗證”"},"​")],-1)),s[29]||(s[29]=t("p",null,[t("img",{src:"https://fedoramagazine.org/wp-content/uploads/2019/02/twofactor-auth-ssh-816x345.png",alt:""})],-1)),s[30]||(s[30]=t("p",null,"每天似乎都有一個安全漏洞的新聞報道，説我們的數據會因此而存在風險。儘管 SSH 是一種遠程連接系統的安全方式，但你仍然可以使它更安全。本文將向你展示如何做到這一點。",-1)),s[31]||(s[31]=t("p",null,[e("此時"),t("ruby",null,[e("雙因子驗證"),t("rt",null,"two-factor authentication")]),e("（2FA）就有用武之地了。即使你禁用密碼並只允許使用公鑰和私鑰進行 SSH 連接，但如果未經授權的用户偷竊了你的密鑰，他仍然可以藉此訪問系統。")],-1)),s[32]||(s[32]=t("p",null,"使用雙因子驗證，你不能僅僅使用 SSH 密鑰連接到服務器，你還需要提供手機上的驗證器應用程序隨機生成的數字。",-1)),t("p",null,[s[1]||(s[1]=e("本文展示的方法是",-1)),s[2]||(s[2]=t("ruby",null,[e("基於時間的一次性密碼"),t("rt",null,"Time-based One-time Password")],-1)),s[3]||(s[3]=e("（TOTP）算法。",-1)),i(a,{href:"https://en.wikipedia.org/wiki/Google_Authenticator"},{default:n(()=>[...s[0]||(s[0]=[e("Google Authenticator",-1)])]),_:1}),s[4]||(s[4]=e(" 用作服務器應用程序。默認情況下，Google Authenticator 在 Fedora 中是可用的。",-1))]),t("p",null,[s[6]||(s[6]=e("至於手機，你可以使用與 TOTP 兼容的任何可以雙路驗證的應用程序。Andorid 或 iOS 有許多可以與 TOTP 和 Google Authenticator 配合使用的免費應用程序。本文與 ",-1)),i(a,{href:"https://freeotp.github.io/"},{default:n(()=>[...s[5]||(s[5]=[e("FreeOTP",-1)])]),_:1}),s[7]||(s[7]=e(" 為例。",-1))]),s[33]||(s[33]=o(`<h3 id="安裝並設置-google-authenticator" tabindex="-1">安裝並設置 Google Authenticator <a class="header-anchor" href="#安裝並設置-google-authenticator" aria-label="Permalink to “安裝並設置 Google Authenticator”">​</a></h3><p>首先，在你的服務器上安裝 Google Authenticator。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf install -y google-authenticator</span></span></code></pre></div><p>運行應用程序：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ google-authenticator</span></span></code></pre></div><p>該應用程序提供了一系列問題。下面的片段展示瞭如何進行合理的安全設置：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Do you want authentication tokens to be time-based (y/n) y</span></span>
<span class="line"><span>Do you want me to update your &quot;/home/user/.google_authenticator&quot; file (y/n)? y</span></span></code></pre></div><p>這個應用程序為你提供一個密鑰、驗證碼和恢復碼。把它們放在安全的地方。如果你丟失了手機，恢復碼是訪問服務器的<strong>唯一</strong>方式。</p><h3 id="設置手機驗證" tabindex="-1">設置手機驗證 <a class="header-anchor" href="#設置手機驗證" aria-label="Permalink to “設置手機驗證”">​</a></h3><p>在你的手機上安裝驗證器應用程序（FreeOTP）。如果你有一台安卓手機，那麼你可以在 Google Play 中找到它，也可以在蘋果 iPhone 的 iTunes 商店中找到它。</p><p>Google Authenticator 會在屏幕上顯示一個二維碼。打開手機上的 FreeOTP 應用程序，選擇添加新賬户，在應用程序頂部選擇二維碼形狀工具，然後掃描二維碼即可。設置完成後，在每次遠程連接服務器時，你必須提供驗證器應用程序生成的隨機數。</p><h3 id="完成配置" tabindex="-1">完成配置 <a class="header-anchor" href="#完成配置" aria-label="Permalink to “完成配置”">​</a></h3><p>應用程序會向你詢問更多的問題。下面示例展示瞭如何設置合理的安全配置。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Do you want to disallow multiple uses of the same authentication token? This restricts you to one login about every 30s, but it increases your chances to notice or even prevent man-in-the-middle attacks (y/n) y</span></span>
<span class="line"><span>By default, tokens are good for 30 seconds. In order to compensate for possible time-skew between the client and the server, we allow an extra token before and after the current time. If you experience problems with poor time synchronization, you can increase the window from its default size of +-1min (window size of 3) to about +-4min (window size of 17 acceptable tokens).</span></span>
<span class="line"><span>Do you want to do so? (y/n) n</span></span>
<span class="line"><span>If the computer that you are logging into isn&#39;t hardened against brute-force login attempts, you can enable rate-limiting for the authentication module. By default, this limits attackers to no more than 3 login attempts every 30s.</span></span>
<span class="line"><span>Do you want to enable rate-limiting (y/n) y</span></span></code></pre></div><p>現在，你必須設置 SSH 來利用新的雙路驗證。</p><h3 id="配置-ssh" tabindex="-1">配置 SSH <a class="header-anchor" href="#配置-ssh" aria-label="Permalink to “配置 SSH”">​</a></h3><p>在完成此步驟之前，<strong>確保你已使用公鑰建立了一個可用的 SSH 連接</strong>，因為我們將禁用密碼連接。如果出現問題或錯誤，一個已經建立的連接將允許你修復問題。</p>`,17)),t("p",null,[s[9]||(s[9]=e("在你的服務器上，使用 ",-1)),i(a,{href:"https://fedoramagazine.org/howto-use-sudo/"},{default:n(()=>[...s[8]||(s[8]=[e("sudo",-1)])]),_:1}),s[10]||(s[10]=e(" 編輯 ",-1)),s[11]||(s[11]=t("code",null,"/etc/pam.d/sshd",-1)),s[12]||(s[12]=e(" 文件。",-1))]),s[34]||(s[34]=o(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo vi /etc/pam.d/ssh</span></span></code></pre></div><p>註釋掉 <code>auth substack password-auth</code> 這一行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>#auth       substack     password-auth</span></span></code></pre></div><p>將以下行添加到文件底部：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>auth sufficient pam_google_authenticator.so</span></span></code></pre></div><p>保存並關閉文件。然後編輯 <code>/etc/ssh/sshd_config</code> 文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo vi /etc/ssh/sshd_config</span></span></code></pre></div><p>找到 <code>ChallengeResponseAuthentication</code> 這一行並將其更改為 <code>yes</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ChallengeResponseAuthentication yes</span></span></code></pre></div><p>找到 <code>PasswordAuthentication</code> 這一行並將其更改為 <code>no</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>PasswordAuthentication no</span></span></code></pre></div><p>將以下行添加到文件底部：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>AuthenticationMethods publickey,password publickey,keyboard-interactive</span></span></code></pre></div><p>保存並關閉文件，然後重新啓動 SSH：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo systemctl restart sshd</span></span></code></pre></div><h3 id="測試雙因子驗證" tabindex="-1">測試雙因子驗證 <a class="header-anchor" href="#測試雙因子驗證" aria-label="Permalink to “測試雙因子驗證”">​</a></h3><p>當你嘗試連接到服務器時，系統會提示你輸入驗證碼：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[user@client ~]$ ssh user@example.com</span></span>
<span class="line"><span>Verification code:</span></span></code></pre></div><p>驗證碼由你手機上的驗證器應用程序隨機生成。由於這個數字每隔幾秒就會發生變化，因此你需要在它變化之前輸入它。</p><p><img src="https://fedoramagazine.org/wp-content/uploads/2019/02/freeotp-1.png" alt=""></p><p>如果你不輸入驗證碼，你將無法訪問系統，你會收到一個權限被拒絕的錯誤：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[user@client ~]$ ssh user@example.com</span></span>
<span class="line"><span>Verification code:</span></span>
<span class="line"><span>Verification code:</span></span>
<span class="line"><span>Verification code:</span></span>
<span class="line"><span>Permission denied (keyboard-interactive).</span></span>
<span class="line"><span>[user@client ~]$</span></span></code></pre></div><h3 id="結論" tabindex="-1">結論 <a class="header-anchor" href="#結論" aria-label="Permalink to “結論”">​</a></h3><p>通過添加這種簡單的雙路驗證，現在未經授權的用户訪問你的服務器將變得更加困難。</p><hr>`,25)),t("p",null,[s[14]||(s[14]=e("via: ",-1)),i(a,{href:"https://fedoramagazine.org/two-factor-authentication-ssh-fedora/"},{default:n(()=>[...s[13]||(s[13]=[e("https://fedoramagazine.org/two-factor-authentication-ssh-fedora/",-1)])]),_:1})]),t("p",null,[s[19]||(s[19]=e("作者：",-1)),i(a,{href:"https://fedoramagazine.org/author/rcurtiswarfield/"},{default:n(()=>[...s[15]||(s[15]=[e("Curt Warfield",-1)])]),_:1}),s[20]||(s[20]=e(" 選題：",-1)),i(a,{href:"https://github.com/lujun9972"},{default:n(()=>[...s[16]||(s[16]=[e("lujun9972",-1)])]),_:1}),s[21]||(s[21]=e(" 譯者：",-1)),i(a,{href:"https://github.com/MjSeven"},{default:n(()=>[...s[17]||(s[17]=[e("MjSeven",-1)])]),_:1}),s[22]||(s[22]=e(" 校對：",-1)),i(a,{href:"https://github.com/wxy"},{default:n(()=>[...s[18]||(s[18]=[e("wxy",-1)])]),_:1})]),t("p",null,[s[25]||(s[25]=e("本文由 ",-1)),i(a,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...s[23]||(s[23]=[e("LCTT",-1)])]),_:1}),s[26]||(s[26]=e(" 原創編譯，",-1)),i(a,{href:"https://linux.cn/"},{default:n(()=>[...s[24]||(s[24]=[e("Linux中國",-1)])]),_:1}),s[27]||(s[27]=e(" 榮譽推出",-1))])])}const C=l(h,[["render",g]]);export{S as __pageData,C as default};
